import json
import re

class FormatDetector:
    def __init__(self):
        # Basic regex for syslog header (e.g., "Oct 11 22:14:15 mymachine su: ...")
        self.syslog_pattern = re.compile(r'^[A-Z][a-z]{2}\s+\d+\s+\d{2}:\d{2}:\d{2}\s+\S+\s+')
        # Basic regex for Apache/Nginx access log
        self.apache_pattern = re.compile(r'^\S+\s+\S+\s+\S+\s+\[[^\]]+\]\s+"[^"]+"\s+\d+\s+\d+')

    def detect(self, log_entry: str) -> str:
        # Aggressively strip quotes/commas in case the user pasted the JSON array syntax
        log_entry = log_entry.strip().strip(',').strip('"').strip("'").strip()

        if not log_entry or log_entry in ('[', ']'):
            return "empty"

        # Try JSON
        if log_entry.startswith('{') and log_entry.endswith('}'):
            try:
                log_to_test = log_entry.replace('\\"', '"')
                json.loads(log_to_test)
                return "json"
            except json.JSONDecodeError:
                pass

        # Try Syslog
        if self.syslog_pattern.match(log_entry):
            return "syslog"

        # Try Apache
        if self.apache_pattern.match(log_entry):
            return "apache"

        # Default to unstructured
        return "unstructured"

