document.getElementById('process-btn').addEventListener('click', async () => {
    const inputArea = document.getElementById('log-input');
    const outputContainer = document.getElementById('output-container') || document.querySelector('.output-container');
    const btn = document.getElementById('process-btn');

    const rawText = inputArea.value.trim();
    if (!rawText) {
        outputContainer.innerHTML = '<div style="color: #fca5a5; padding: 1rem;">Please enter some logs to process.</div>';
        return;
    }

    // Split by lines, remove empty lines
    const logs = rawText.split('\n').filter(line => line.trim().length > 0);

    btn.textContent = 'Processing...';
    btn.disabled = true;

    try {
        const response = await fetch('/api/logs/ingest', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({ logs })
        });

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();

        outputContainer.innerHTML = '';

        if (data.processed_logs.length === 0) {
            outputContainer.innerHTML = '<div style="color: #94a3b8; text-align: center; padding-top: 2rem;">No logs processed.</div>';
            return;
        }

        data.processed_logs.forEach(log => {
            const card = document.createElement('div');
            card.className = 'log-card';

            const formatBadge = document.createElement('span');
            formatBadge.className = `badge badge-${log.format_detected}`;
            formatBadge.textContent = log.format_detected.toUpperCase();

            const originalLog = document.createElement('div');
            originalLog.className = 'original-log';
            originalLog.textContent = log.original_log;

            const parsedData = document.createElement('div');
            parsedData.className = 'parsed-data';

            const fields = log.normalized_fields || log.parsed_fields || {};
            let fieldsHtml = '';
            for (const [k, v] of Object.entries(fields)) {
                if (k === 'template' || k === 'template_id') continue; 

                let valToDisplay = v;
                if (k === 'extracted_parameters') {
                    if (Array.isArray(v) && v.length > 0) {
                        valToDisplay = v.map(p => p[0]).join(', ');
                    } else {
                        valToDisplay = 'None (Learned as pure template)';
                    }
                }

                fieldsHtml += `<div class="field-row"><span class="field-key">${k}</span><span class="field-value">${valToDisplay}</span></div>`;
            }

            if (fields.template) {
                fieldsHtml += `<div class="field-row template-row"><span class="field-key">template</span><span class="field-value template-val">${fields.template}</span></div>`;
            }

            parsedData.innerHTML = fieldsHtml;

            card.appendChild(formatBadge);
            card.appendChild(originalLog);
            card.appendChild(parsedData);

            outputContainer.appendChild(card);
        });

        outputContainer.style.opacity = 0;
        setTimeout(() => {
            outputContainer.style.transition = 'opacity 0.5s ease';
            outputContainer.style.opacity = 1;
        }, 50);

    } catch (error) {
        outputContainer.innerHTML = `<div style="color: #fca5a5; padding: 1rem;">Error processing logs:<br>${error.message}</div>`;
    } finally {
        btn.textContent = 'Process Logs';
        btn.disabled = false;
    }
});

