import json
import re

class UniversalParser:
    def __init__(self):
        # Execution Tier: In-memory cache for fast path execution
        self.cache = {}

    def fingerprint(self, log_entry: str) -> str:
        # A simple structural hash to fingerprint the log line
        # Replace numbers with <NUM> and common distinct things to find structural shape
        s = re.sub(r'\d+', '<NUM>', log_entry)
        # For simplicity in the demo, we hash the first 15 structural characters 
        # or use regex-based fingerprinting.
        # Actually, let's just use the shape of the alphanumeric characters
        s = re.sub(r'[a-zA-Z]+', '<WORD>', s)
        return hash(s)

    def parse_with_rule(self, log_entry: str, rule: dict) -> dict:
        result = {
            "parsed_fields": {}
        }

        method = rule.get("parse_method")

        if method == "json":
            result["parsed_fields"] = json.loads(log_entry.replace('\\"', '"'))

        elif method == "regex":
            pattern = rule.get("regex")
            match = re.match(pattern, log_entry)
            if match:
                fields = rule.get("fields", [])
                for i, field_name in enumerate(fields):
                    if i < len(match.groups()):
                        result["parsed_fields"][field_name] = match.group(i+1)
            else:
                # If regex fails despite caching, fallback to raw
                result["parsed_fields"]["raw_message"] = log_entry

        elif method == "csv":
            delimiter = rule.get("delimiter", ",")
            parts = log_entry.split(delimiter)
            fields = rule.get("fields", [])
            for i, part in enumerate(parts):
                field_name = fields[i] if i < len(fields) else f"field_{i}"
                result["parsed_fields"][field_name] = part.strip()

        else:
            result["parsed_fields"]["raw_message"] = log_entry

        return result

