import pandas as pd

class Normalizer:
    def __init__(self):
        # Strict schema requirement:
        # { timestamp, source, event_type, severity, raw, ...any extra fields }

        self.timestamp_fields = ['time', 'date', 'ts', '@timestamp', 'datetime']
        self.severity_fields = ['level', 'severity', 'log_level']
        self.source_fields = ['host', 'source', 'ip', 'hostname']
        self.event_type_fields = ['process', 'event', 'action', 'type']

    def normalize(self, parsed_data: dict, raw_log: str) -> dict:
        fields = parsed_data.get("parsed_fields", {})
        if not isinstance(fields, dict):
            return parsed_data

        normalized = {
            "timestamp": None,
            "source": None,
            "event_type": None,
            "severity": None,
            "raw": raw_log
        }

        for key, value in fields.items():
            key_lower = key.lower()

            # Normalize Timestamp
            if key_lower in self.timestamp_fields or key_lower == 'timestamp':
                try:
                    ts = pd.to_datetime(value)
                    normalized['timestamp'] = ts.isoformat()
                except Exception:
                    normalized['timestamp'] = str(value)
                continue

            # Normalize Severity
            if key_lower in self.severity_fields:
                normalized['severity'] = str(value).upper()
                continue

            # Normalize Source
            if key_lower in self.source_fields:
                normalized['source'] = str(value)
                continue

            # Normalize Event Type
            if key_lower in self.event_type_fields:
                normalized['event_type'] = str(value)
                continue

            # Keep other fields as is
            normalized[key] = value

        return normalized

