document.addEventListener('DOMContentLoaded', () => {
    const sampleSelect = document.getElementById('sample-select');
    const logInput = document.getElementById('log-input');
    const processBtn = document.getElementById('process-btn');

    // UI Elements
    const summaryRow = document.getElementById('summary-row');
    const valMode = document.getElementById('val-mode');
    const valFormat = document.getElementById('val-format');
    const valLatency = document.getElementById('val-latency');
    const cardMode = document.getElementById('card-mode');

    const tableSection = document.getElementById('table-section');
    const fieldsBody = document.getElementById('fields-body');

    const outputSection = document.getElementById('output-section');
    const logOutput = document.getElementById('log-output');

    // Handle dropdown selection
    sampleSelect.addEventListener('change', (e) => {
        if (e.target.value) {
            logInput.value = e.target.value;
        }
    });

    processBtn.addEventListener('click', async () => {
        const rawText = logInput.value.trim();
        if (!rawText) {
            alert('Please enter a log to process.');
            return;
        }

        processBtn.textContent = 'Running Pipeline...';
        processBtn.disabled = true;

        // Reset UI
        summaryRow.style.display = 'none';
        tableSection.style.display = 'none';
        outputSection.style.display = 'none';

        try {
            // We only process the first line to keep the demo clean and linear as requested
            const logs = [rawText.split('\n')[0]];

            const response = await fetch('/api/logs/ingest', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ logs })
            });

            if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
            const data = await response.json();

            if (data.processed_logs.length === 0) return;

            const result = data.processed_logs[0];

            // 1. Populate Summary Row
            valMode.textContent = result.mode;
            valFormat.textContent = result.format;
            valLatency.textContent = `${result.latency_ms} ms`;

            // Highlight caching difference
            cardMode.className = 'stat-card'; // reset
            if (result.mode === 'Cached') {
                cardMode.classList.add('mode-cached');
                valMode.textContent = 'Cached (Fast Path)';
            } else {
                cardMode.classList.add('mode-discovery');
                valMode.textContent = 'Discovery (LLM Inference)';
            }
            summaryRow.style.display = 'grid';

            // 2. Populate Inferred Fields Table
            fieldsBody.innerHTML = '';
            for (const [key, value] of Object.entries(result.extracted_fields)) {
                if (key === 'raw_message') continue;
                const tr = document.createElement('tr');
                tr.innerHTML = `<td>${key}</td><td>${value}</td>`;
                fieldsBody.appendChild(tr);
            }

            if (fieldsBody.innerHTML === '') {
                fieldsBody.innerHTML = '<tr><td colspan="2" style="text-align:center; color:#94a3b8">No fields extracted (Unstructured fallback)</td></tr>';
            }
            tableSection.style.display = 'block';

            // 3. Populate Normalized JSON
            logOutput.textContent = JSON.stringify(result.normalized, null, 2);
            outputSection.style.display = 'block';

        } catch (error) {
            alert(`Error: ${error.message}`);
        } finally {
            processBtn.textContent = 'Run Pipeline';
            processBtn.disabled = false;
        }
    });
});

