import json
import re

class UniversalParser:
    def __init__(self):
        # Execution Tier: In-memory cache for fast path execution
        self.cache = {}

    def fingerprint(self, log_entry: str) -> dict:
        """Compute structural features, not content-based format names."""
        s = log_entry.strip()
        is_json = False
        if s.startswith('{') and s.endswith('}'):
            try: 
                json.loads(s.replace('\\"', '"'))
                is_json = True
            except: 
                pass

        # Count common structural delimiters
        features = {
            "is_json": is_json,
            "tok_count": len(s.split()),
            "pipe_count": s.count('|'),
            "comma_count": s.count(','),
            "eq_count": s.count('='),
            "colon_count": s.count(':'),
            "bracket_count": s.count('['),
            "len_bucket": len(s) // 50
        }
        return features

    def find_cached_rule(self, features: dict):
        """Find the nearest matching structural fingerprint."""
        for fp_str, rule in self.cache.items():
            cached_feat = json.loads(fp_str)
            # If JSON, it's a structural match immediately
            if cached_feat["is_json"] and features["is_json"]:
                return fp_str, rule

            # If not JSON, compare structural delimiters. 
            # We allow minor variation in token count, but require delimiter shapes to match.
            if not features["is_json"]:
                if (cached_feat["pipe_count"] == features["pipe_count"] and
                    cached_feat["comma_count"] == features["comma_count"] and
                    cached_feat["eq_count"] == features["eq_count"] and
                    cached_feat["bracket_count"] == features["bracket_count"] and
                    abs(cached_feat["tok_count"] - features["tok_count"]) <= 4):
                    return fp_str, rule
        return None, None

    def store_rule(self, features: dict, rule: dict):
        fp_str = json.dumps(features, sort_keys=True)
        self.cache[fp_str] = rule

    def parse_with_rule(self, log_entry: str, rule: dict) -> dict:
        """Execute extraction purely deterministically based on the cached rule."""
        result = {"parsed_fields": {}}
        method = rule.get("method")

        if method == "json":
            result["parsed_fields"] = json.loads(log_entry.replace('\\"', '"'))

        elif method == "delimiter":
            delim = rule.get("delimiter")
            parts = log_entry.split(delim)
            for i, p in enumerate(parts):
                result["parsed_fields"][f"field_{i}"] = p.strip()

        elif method == "key_value":
            delim = rule.get("kv_delim")
            pairs = re.findall(rf'([a-zA-Z0-9_-]+){delim}([^ ]+)', log_entry)
            for k, v in pairs:
                result["parsed_fields"][k] = v

        elif method == "positional":
            parts = log_entry.split()
            for i, p in enumerate(parts):
                result["parsed_fields"][f"field_{i}"] = p.strip()

        else:
            result["parsed_fields"]["raw_message"] = log_entry

        return result

