class LLMDiscoveryEngine:
    """
    Discovery Tier: Infers schema purely structurally. 
    Strictly forbids format-named hardcoding (e.g. 'if format == syslog').
    """

    def run_inference(self, log_entry: str, features: dict) -> dict:
        # SIMULATE LLM / DISCOVERY LATENCY
        time.sleep(1.2)

        # ---------------------------------------------------------
        # CLOUD LLM PATH (Stubbed for security/offline demo)
        # ---------------------------------------------------------
        # prompt = f"Analyze this log structure: {log_entry}. Return JSON field map."
        # llm_response = call_cloud_llm(prompt) 
        # if llm_response.is_valid(): return llm_response.rule

        # ---------------------------------------------------------
        # OFFLINE FALLBACK CHAIN 
        # A chain of generic structural heuristics.
        # ---------------------------------------------------------

        # 1. JSON Structural Fallback
        if features["is_json"]:
            return {
                "signature": "JSON Object",
                "method": "json"
            }

        # 2. Consistent Delimiter Fallback
        # Check if pipe or comma exists in sufficient quantity to be a delimiter
        if features["pipe_count"] >= 2:
            return {
                "signature": f"Pipe-Delimited ({features['pipe_count']+1} fields)",
                "method": "delimiter",
                "delimiter": "|"
            }

        if features["comma_count"] >= 2:
            return {
                "signature": f"Comma-Separated ({features['comma_count']+1} fields)",
                "method": "delimiter",
                "delimiter": ","
            }

        # 3. Key-Value Fallback
        if features["eq_count"] >= 2:
            return {
                "signature": "Key=Value Pairs",
                "method": "key_value",
                "kv_delim": "="
            }

        if features["colon_count"] >= 2:
            return {
                "signature": "Key:Value Pairs",
                "method": "key_value",
                "kv_delim": ":"
            }

        # 4. Positional Whitespace Fallback (Catch-all)
        return {
            "signature": f"Positional Space-Delimited ({features['tok_count']} tokens)",
            "method": "positional"
        }

import pandas as pd
import dateutil.parser

class Normalizer:
    def __init__(self):
        # We look for common keywords structurally, not assuming format
        self.timestamp_keywords = ['time', 'date', 'ts', '@timestamp', 'datetime', 'timestamp']
        self.severity_keywords = ['level', 'severity', 'log_level']
        self.source_keywords = ['host', 'source', 'ip', 'hostname']
        self.event_type_keywords = ['process', 'event', 'action', 'type', 'message', 'msg']

    def normalize(self, parsed_data: dict, raw_log: str) -> dict:
        fields = parsed_data.get("parsed_fields", {})
        if not isinstance(fields, dict):
            return {"raw": raw_log, "extra": fields}

        normalized = {
            "timestamp": None,
            "source": None,
            "event_type": None,
            "severity": None,
            "raw": raw_log,
            "extra": {}
        }

        # Heuristically map extracted positional or named fields
        for key, value in fields.items():
            key_lower = str(key).lower()
            value_str = str(value).strip()

            # Timestamp heuristic (by name or shape)
            if key_lower in self.timestamp_keywords or (not normalized['timestamp'] and self.looks_like_timestamp(value_str)):
                if not normalized['timestamp']:
                    try:
                        ts = dateutil.parser.parse(value_str)
                        normalized['timestamp'] = ts.isoformat()
                        continue
                    except:
                        # Ambiguous timestamp, push to extra instead of guessing silently
                        normalized['extra'][key] = value
                else:
                    normalized['extra'][key] = value
                continue

            # Severity heuristic
            if key_lower in self.severity_keywords or (not normalized['severity'] and self.looks_like_severity(value_str)):
                if not normalized['severity']:
                    normalized['severity'] = value_str.upper()
                else:
                    normalized['extra'][key] = value
                continue

            # Source heuristic
            if key_lower in self.source_keywords:
                normalized['source'] = value_str
                continue

            # Event Type / Message heuristic
            if key_lower in self.event_type_keywords:
                normalized['event_type'] = value_str
                continue

            # Anything else goes to extra!
            normalized['extra'][key] = value

        return normalized

    def looks_like_timestamp(self, val: str) -> bool:
        # Very rough structural heuristic for timestamps (e.g. 2026-09-13 or Oct 11 22:14)
        if len(val) < 8 or len(val) > 35: return False
        if ('-' in val and ':' in val) or ('/' in val and ':' in val) or val.count(':') >= 2:
            return True
        return False

    def looks_like_severity(self, val: str) -> bool:
        return val.upper() in ['INFO', 'WARN', 'WARNING', 'ERROR', 'CRITICAL', 'FATAL', 'DEBUG', 'TRACE']

document.addEventListener('DOMContentLoaded', () => {
    const sampleSelect = document.getElementById('sample-select');
    const logInput = document.getElementById('log-input');
    const processBtn = document.getElementById('process-btn');
    const resultsContainer = document.getElementById('results-container');
    const cacheOutput = document.getElementById('cache-output');
    const refreshCacheBtn = document.getElementById('refresh-cache-btn');
    const template = document.getElementById('result-card-template');

    // Handle dropdown selection
    sampleSelect.addEventListener('change', (e) => {
        if (e.target.value) {
            // Append if there's already text, otherwise replace
            if (logInput.value.trim()) {
                logInput.value = logInput.value.trim() + '\n' + e.target.value;
            } else {
                logInput.value = e.target.value;
            }
        }
    });

    const refreshCache = async () => {
        try {
            const res = await fetch('/api/logs/cache');
            const data = await res.json();
            if (data.cache.length === 0) {
                cacheOutput.textContent = 'Cache is currently empty.';
            } else {
                cacheOutput.textContent = JSON.stringify(data.cache, null, 2);
            }
        } catch(e) {
            console.error('Failed to fetch cache', e);
        }
    };

    refreshCacheBtn.addEventListener('click', refreshCache);
    refreshCache(); // initial load

    processBtn.addEventListener('click', async () => {
        const rawText = logInput.value.trim();
        if (!rawText) {
            alert('Please enter a log to process.');
            return;
        }

        processBtn.textContent = 'Running Pipeline...';
        processBtn.disabled = true;

        resultsContainer.innerHTML = ''; // Clear previous runs

        try {
            const logs = rawText.split('\n'); // Send all lines

            const response = await fetch('/api/logs/ingest', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ logs })
            });

            if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
            const data = await response.json();

            data.processed_logs.forEach(result => {
                const clone = template.content.cloneNode(true);

                const valMode = clone.querySelector('.val-mode');
                const valFormat = clone.querySelector('.val-format');
                const valLatency = clone.querySelector('.val-latency');
                const modeCard = clone.querySelector('.mode-card');
                const fieldsBody = clone.querySelector('.fields-body');
                const logOutput = clone.querySelector('.log-output');

                valMode.textContent = result.mode;
                valFormat.textContent = result.format;
                valLatency.textContent = `${result.latency_ms} ms`;

                // Highlight caching difference
                if (result.mode === 'Cached') {
                    modeCard.classList.add('mode-cached');
                    valMode.textContent = 'Cached (Fast Path)';
                } else {
                    modeCard.classList.add('mode-discovery');
                    valMode.textContent = 'Discovery (Inference)';
                }

                // Populate Inferred Fields Table
                for (const [key, value] of Object.entries(result.extracted_fields)) {
                    if (key === 'raw_message') continue;
                    const tr = document.createElement('tr');
                    tr.innerHTML = `<td>${key}</td><td>${value}</td>`;
                    fieldsBody.appendChild(tr);
                }

                if (fieldsBody.innerHTML === '') {
                    fieldsBody.innerHTML = '<tr><td colspan="2" style="text-align:center; color:#94a3b8">No fields extracted (Unstructured fallback)</td></tr>';
                }

                // Populate Normalized JSON
                logOutput.textContent = JSON.stringify(result.normalized, null, 2);

                resultsContainer.appendChild(clone);
            });

            // Auto refresh cache inspector
            await refreshCache();

        } catch (error) {
            alert(`Error: ${error.message}`);
        } finally {
            processBtn.textContent = 'Run Pipeline';
            processBtn.disabled = false;
        }
    });
});

